/* The Society Atlas V2 — wording for the first eighteen encounters as this edition shows
   them. The first edition's own text is untouched in dist/legacy. Facts in the narrator
   lines are the same as before; only the phrasing has changed. */
(function () {
  'use strict';
  const D = window.ATLAS_DATA; if (!D || !Array.isArray(D.encounters)) return;
  const V = {
    1: { objective: 'Find the Penn fieldwork station and track down the street the survey skipped.',
      dialogue: ['Every table starts with choices. Whom did we visit? What did we ask? Which boxes did we give people to tick? Look at how the numbers were gathered before you believe what they say.', 'The survey route in this made-up sample was the easy one, and it missed a whole street. Go and talk to those households before anyone decides that Eastbank just doesn’t care for the festival.', 'Narrator: Du Bois came to Penn as an Assistant in Sociology to carry out his Philadelphia study. He was never given a permanent faculty office there, so this meeting is set at a fieldwork station.'],
      limitation: 'A handful of invented interviews can’t speak for a district. And the categories a survey used a century ago need to be read with care.', evidence: 'The easy route skipped a street. Once its households were counted, the picture changed.' },
    2: { objective: 'Find the model room and try out different rules for moving house.',
      dialogue: ['Put the households on the board, guess what will happen, then run the rule. You should be able to say why each one moved.', 'The pattern you end up with can be much stronger than anything the households wanted. Don’t trust one run. Change the starting layout and try again.', 'Narrator: This is a small version of the model, and it shows one way such a pattern could arise. Housing discrimination, prices, policy and much else are left out of it.'],
      limitation: 'Showing that something could happen this way doesn’t show that it did. The real causes of segregation are a separate question.', transfer: 'What would you need to find out to tell “people sorted themselves” apart from “people couldn’t get there”?', evidence: 'On this board, mild preferences about neighbors were enough to produce sharply divided blocks.' },
    3: { objective: 'Find the message room and get word beyond one tight circle of friends.',
      dialogue: ['You only have a few messages to send. Count how many different people hear the news. Telling the same person twice gets you nothing.', 'Your close friends mostly know each other. The acquaintance who also knows another crowd is the one who carries news somewhere new. Look at the actual map of who knows whom, because how close two people are doesn’t settle it.', 'Now compare hearing about something with doing it. An invitation can cross a bridge when a habit that takes effort will not.'],
      limitation: 'Weak ties aren’t always the better ones. And hearing about something is a long way from acting on it.', evidence: 'In this network the contacts who bridged two groups reached new people, while close friends mostly reached the same ones again.' },
    4: { objective: 'Find the Workshop and work out a water rule that people can live with.',
      dialogue: ['What the upstream farm takes decides what is left downstream. Try a rule for sharing the water, watch the upkeep and the withdrawals, and change the rule as the seasons go by.', 'A rule can look fair on paper and still be impossible to check or to change. Ask who had a say in making it.', 'Narrator: The Workshop at Indiana is real. This channel, the people along it and what happens to them were made up for the lesson.'],
      limitation: 'How well a rule works depends on the place and the people. No checklist settles it everywhere.', evidence: 'Upkeep, keeping watch and who gets a say all changed how well the shared channel worked.' },
    5: { objective: 'Find the causal seminar and learn to tell seeing from doing.',
      dialogue: ['Draw what you believe as arrows. Then ask what those arrows let you conclude. A diagram like this is a claim about the world, so be ready to defend it.', 'Watching people who happen to have a travel pass is one thing. Handing passes out is another. Before you compare the two groups, look for something that causes both the pass and the outcome.', 'If you can’t defend the arrows, go and measure more, or design a better experiment.'],
      limitation: 'Drawing an arrow doesn’t make it true. What you can conclude depends on your assumptions and on what you measured.', evidence: 'When something else drives both, the pattern you observe and the effect of stepping in come apart.' },
    6: { objective: 'Find the network lab and grow two networks by two different rules.',
      dialogue: ['Grow two networks from the same start. In one of them, a node that already has many links is more likely to get the next one.', 'Count the links each node ends up with. Then knock out nodes at random, and after that knock out the best connected ones. Say what happened in these two networks and no more.', 'A small graph can show how hubs might form. It can’t prove that real social life follows a power law.'],
      limitation: 'Plenty of social networks are not scale-free, and a small simulated graph can’t establish a law about real ones.', evidence: 'The rule for adding links decided whether hubs formed, and how badly the network suffered when nodes were removed.' },
    7: { objective: 'Find the listening room and run the same songs in separate worlds.',
      dialogue: ['Put the simulated listeners into two groups. One group can see what is popular and the other can’t. Keep the comparison that simple.', 'Now run another world from scratch. A song can finish in a different place even though it is the same song. Look at two things separately: how unequal the charts are, and how predictable.', 'Narrator: These listeners are a few lines of code. They are not the people who took part in the original Music Lab. The short tunes and the results in the game are our own.'],
      limitation: 'A simulation of people influencing each other is not the experiment with real people, and it tells you nothing about what anyone actually likes.', evidence: 'When listeners could see what was popular, early luck was magnified, and separate worlds ended up with different charts.' },
    8: { objective: 'Find the diffusion room and compare hearing it once with hearing it from several friends.',
      dialogue: ['To begin with, let one friend be enough to convince someone. Then require several. Keep an eye on who can still be reached.', 'Start it among neighbors who all know each other, then among people scattered far apart. A long-distance link is a fine way to pass on news, but it may not give enough encouragement for something that takes effort.', 'Narrator: The original study was an online experiment about health behavior. This festival network is a new and much simpler version.'],
      limitation: 'No one shape of network wins every time. It depends on what is spreading, how much convincing people need and where it starts.', evidence: 'Whether one friend was enough or several were needed changed which starting points and which links helped it spread.' },
    9: { objective: 'Find the text-analysis office and work out why posts are disappearing.',
      dialogue: ['Gary King: Start with two possible reasons for the missing posts. Be careful that the categories you choose don’t quietly hand the win to one of them.', 'Jennifer Pan: Code criticism and calls to gather as two separate things. And save a copy of what was posted before anything is deleted, as well as after.', 'Margaret Roberts: Check your labels against the posts themselves. If you only read what survived, you have thrown away half of what you are trying to explain.', 'Narrator: The team’s 2013 study was about censorship in China. The Bellwether platform is invented for teaching. It is not their data, and it is not a rule for every country or platform.'],
      limitation: 'Comparing snapshots is not a randomized experiment. How posts were labeled and which ones were collected still matter a great deal.', evidence: 'Comparing before and after showed the posts that an analysis of the survivors alone would never have seen.' },
    10: { objective: 'Find the forecasting office and check a data source that keeps changing.',
      dialogue: ['A forecast can fit last year beautifully and fall over this year. Compare how it did before and after the platform changed how it works.', 'Set a properly measured benchmark and a very simple baseline next to the online data. Piling up more records from the same shifting source may not help at all.', 'Narrator: The Google Flu paper is the real study behind this visit. Bellwether’s forecast and its numbers were made up for the exercise.'],
      limitation: 'What people do online is not a fixed measure of what is happening in the world. The platform changes, and the trace changes with it.', evidence: 'Testing on later months, against an outside benchmark, showed a drift that the original fit had hidden.' },
    11: { objective: 'Find the vision lab and work out what street photographs can and can’t tell you.',
      dialogue: ['Timnit Gebru: Follow the chain from a street photograph, to what the software detects, to the claim made about a whole area. Look for errors and missing views at every link.', 'Fei-Fei Li: A gate that stands open in a photograph taken at noon tells you nothing about the evening of the festival. Check when and where each picture was taken, and in what conditions.', 'Narrator: The 2017 paper studied cars and regional totals. The puzzle about the evening route is new. Gebru finished her doctorate at Stanford in 2017, and the game does not call her a Stanford professor.'],
      limitation: 'Spotting an object in a picture says nothing about who uses it or owns it, or what they are like. Results from one place have to be checked again before they are applied to another.', evidence: 'Knowing where and when each image was taken, and testing on images held back, separated what the detections could support from claims about the evening that they could not.' },
    12: { objective: 'Find Desmarais’s office, then test a codebook and a simulated sample.',
      dialogue: ['Decide what you are measuring first. Someone can dislike how the festival is run and still want it to happen. Someone else can sound cheerful and be against expanding it. Tone and position are different things.', 'Improve the codebook on practice examples, then stop changing it before you try it on statements it has never seen. And read the mistakes. The accuracy figure alone won’t tell you what went wrong.', 'Then set a scripted, simulated sample beside a benchmark that was drawn up independently. The averages can match while the spread and the relationships are quite different.', 'Narrator: This lesson draws on Desmarais’s interests in method and his teaching in 2023. The separate studies of simulated samples are by Argyle and colleagues and by Bisbee and colleagues. Every model label in the game is scripted.'],
      limitation: 'Change the prompt, the model or the version and the measurement can change too. Simulated respondents have to be checked against real ones and can’t simply stand in for them.', evidence: 'A codebook written for the question, tested on statements held back, made the audit better. Matching averages were not enough to show that the simulated sample was sound.' },
    13: { objective: 'Find Christenson’s office and tell drawing together apart from pulling away.',
      dialogue: ['Two snapshots can look equally divided for quite different reasons. Follow two things separately: people moving closer to their own side, and people moving away from the other.', 'The positions on this map are worked out from who talks to whom. Nobody observed anyone’s ideology directly. Ask what new observation would tell the rival explanations apart.', 'Change the feed filter, check what it assumes, and look for settings that keep people talking across the divide. Division is one outcome among several.'],
      limitation: 'Changing a feed in a small simulation doesn’t show what would happen in the world, and a position worked out from ties is not a direct measure of anyone’s beliefs.', evidence: 'Following movement within groups and between them separately told apart two processes that a single snapshot could not.' },
    14: { objective: 'Find the decision room and compare ways of deciding when looking costs something.',
      dialogue: ['Looking for the best site uses up time and money. Go through the options one at a time and keep a count of what each look costs you.', 'Compare checking every site with stopping at the first one that is good enough. Change the budget and see when the two give different answers.', 'A simple rule like this is useful for the job it was built for. Nobody should take it for a description of how everyone decides everything.'],
      limitation: 'The model leaves out how what people hope for, their organizations and what they know all shift over time.', evidence: 'What a search costs, and how good is good enough, changed which site each rule picked and what it was worth in the end.' },
    15: { objective: 'Find the decision seminar and compare two ways of describing the same choice.',
      dialogue: ['Work out what the “gain” version and the “loss” version come to. They are the same outcomes. Pick whichever option you like. Nobody is marking your answer.', 'Now set the simulated responses, which are clearly marked as such, against a model that says wording shouldn’t matter. And look at a case where the effect is weaker.', 'Narrator: Much of Kahneman’s work on judgment under uncertainty was done jointly with Amos Tversky, who died in 1996. The 2002 prize was shared with Vernon Smith, for separate work.'],
      limitation: 'One player’s choice is not an experiment on a population, and how much the wording matters varies from one setting to another.', evidence: 'The same outcomes can be described in two ways, and any prediction about how people will respond has to be checked against responses collected separately.' },
    16: { objective: 'Find the matching office, catch a pair who would both swap, and run deferred acceptance.',
      dialogue: ['Hand out the seminar places using everyone’s preferences and the room sizes. If a student and a seminar would each prefer the other to what they got, you have a blocking pair.', 'Run deferred acceptance and watch who proposes and who is turned down. Then let the other side do the proposing. A stable result does not leave everyone equally pleased.', 'Narrator: This conversation is invented. Gale and Shapley devised the algorithm, and Roth’s contribution includes putting market design to practical use and testing it. Stanford in 2013 is where the visit is set. It is not the affiliation listed for Roth at the time of the prize.'],
      limitation: 'A stable match is not the same as a fair one. It doesn’t mean nobody could gain by misstating what they want, and it doesn’t give everyone their first choice.', evidence: 'With these preferences deferred acceptance left no blocking pairs, and which side proposed changed who came out ahead.' },
    17: { objective: 'Find the study room and design a made-up experiment that could tell you something.',
      dialogue: ['Settle the question, and who gets randomized, before you look at any results. People on the ground will know about obstacles and outcomes that a model built far away would miss.', 'Assign a treatment group and a comparison group and work out the difference. Then check whether the treatment leaked across to the neighbors. A difference by itself is not enough. You need to say how sure you are and why the design supports it.', 'Before anyone scales this up, compare the places you studied with the place you have in mind. These simulated results are no evidence that a real policy works.'],
      limitation: 'Randomizing doesn’t mean the result will hold somewhere else. It doesn’t stop spillovers, and it doesn’t replace careful measurement or ethics.', evidence: 'Assigning the treatment openly and checking for spillovers made it clear how much this simulated comparison could show.' },
    18: { objective: 'Find Acemoglu’s office, compare sets of rules, and get ready for the colloquium.',
      dialogue: ['Compare three things: who is allowed to invest, who collects the returns, and who can change the rules. Over several rounds, watch how the output is shared out as well as how much there is.', 'A made-up society lets you see a mechanism clearly. Whether that mechanism explains a particular place is another matter, and for that you need history and a comparison you can defend.', 'Look at a rival explanation and at a case that doesn’t fit. Then decide what evidence would tell the rules story apart from travel, information or something nobody measured.', 'Narrator: Acemoglu, Johnson and Robinson shared the 2024 economics prize. Robinson’s home institution is Chicago. This meeting, the settlement and the comparison of policies are invented for teaching.'],
      limitation: 'This simulation has not been tested against any real country and is no formula for development. Its assumptions and the history of a place both matter.', evidence: 'In this model, who held the right to decide and how returns were shared changed both how much was invested and who ended up with it.' },
  };
  for (const e of D.encounters) if (V[e.id]) Object.assign(e, V[e.id]);
  if (D.finale) Object.assign(D.finale, {
    introduction: 'Time to put it together. A claim worth making should hold up against a rival explanation, and you should be able to say what evidence would change your mind.',
    evidencePrompt: 'Pick at least three pieces of evidence, admit one limitation and propose a study.',
    ending: 'You leave the hall with a proposal and a long list of questions from the floor. Nobody thinks the matter is settled, least of all you. The residents of Eastbank have asked to see the map before it is printed.',
  });
})();
